import{_ as d,o as e,c as a,a6 as o}from"./chunks/framework.B_q3ZJNF.js";const g=JSON.parse('{"title":"速查表：GLSL 与 WebGL 调用","description":"","frontmatter":{"title":"速查表：GLSL 与 WebGL 调用"},"headers":[],"relativePath":"webgl-graphics-course/cheatsheet.md","filePath":"webgl-graphics-course/docs/cheatsheet.md"}'),r={name:"webgl-graphics-course/cheatsheet.md"};function c(l,t,h,i,n,s){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="速查表-glsl-与-webgl-调用" tabindex="-1">速查表：GLSL 与 WebGL 调用 <a class="header-anchor" href="#速查表-glsl-与-webgl-调用" aria-label="Permalink to &quot;速查表：GLSL 与 WebGL 调用&quot;">​</a></h1><p>全书用过的 GLSL 语法与 WebGL 调用集中在一页。条目全部出自课程正文与演示组件——没教过的 API 不列。</p><h2 id="glsl-速查" tabindex="-1">GLSL 速查 <a class="header-anchor" href="#glsl-速查" aria-label="Permalink to &quot;GLSL 速查&quot;">​</a></h2><h3 id="类型与变量" tabindex="-1">类型与变量 <a class="header-anchor" href="#类型与变量" aria-label="Permalink to &quot;类型与变量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>写法</th><th>是什么</th><th>首教</th></tr></thead><tbody><tr><td><code>float</code></td><td>浮点数。注意 <code>1</code> 与 <code>1.0</code> 不同型——整数喂 float 参数编译失败</td><td>第 2 章</td></tr><tr><td><code>vec2</code> / <code>vec3</code> / <code>vec4</code></td><td>2/3/4 个 float 打包的向量，<code>.xyzw</code> / <code>.rgba</code> / <code>.st</code> 分量选择器与 <code>brg</code> 这类重排（swizzle）都可用</td><td>第 2 章</td></tr><tr><td><code>mat4</code></td><td>4×4 矩阵，构造时按列给数</td><td>第 5 章</td></tr><tr><td><code>attribute</code></td><td>逐顶点输入（坐标、颜色），数据来自缓冲区</td><td>第 2 章</td></tr><tr><td><code>uniform</code></td><td>整次绘制全场统一的只读输入（矩阵、光源、时间）</td><td>第 3 章</td></tr><tr><td><code>varying</code></td><td>顶点着色器传给片元着色器的值，沿线自动插值</td><td>第 2 章</td></tr><tr><td><code>precision mediump float;</code></td><td>精度限定符声明。片元着色器必须写；三档 lowp / mediump / highp</td><td>第 3 章</td></tr></tbody></table><h3 id="内建变量" tabindex="-1">内建变量 <a class="header-anchor" href="#内建变量" aria-label="Permalink to &quot;内建变量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>写法</th><th>是什么</th></tr></thead><tbody><tr><td><code>gl_Position</code></td><td>顶点着色器出口：裁剪坐标（未除 w 的半成品）</td></tr><tr><td><code>gl_FragColor</code></td><td>片元着色器出口：颜色 rgba，写入前超量程被摁回 [0,1]</td></tr></tbody></table><h3 id="全书用过的内建函数" tabindex="-1">全书用过的内建函数 <a class="header-anchor" href="#全书用过的内建函数" aria-label="Permalink to &quot;全书用过的内建函数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>语义</th><th>与实验场对账</th></tr></thead><tbody><tr><td><code>mix(a, b, t)</code></td><td>线性插值，t 不钳制、越界外推</td><td><code>lerp</code>（第 3 章）</td></tr><tr><td><code>clamp(x, lo, hi)</code></td><td>越界收拢</td><td><code>clamp</code>（第 3 章）</td></tr><tr><td><code>smoothstep(e0, e1, x)</code></td><td>两端为 0/1 的 S 形整形，输入钳制</td><td><code>smoothstep</code>（第 3 章；第 13 章雾复用）</td></tr><tr><td><code>dot(a, b)</code> / <code>cross(a, b)</code></td><td>点积 / 叉积</td><td>第 4 章八件套同名同义</td></tr><tr><td><code>normalize(v)</code></td><td>归一化。零向量结果未定义（实验场定死返回 [0,0,0]，见<a href="./divergences.html">简化清单</a>）</td><td>第 4 章</td></tr><tr><td><code>length(v)</code> / <code>distance(a, b)</code></td><td>长度 / 距离</td><td>第 4 章</td></tr><tr><td><code>reflect(I, N)</code></td><td>反射方向：I − 2·dot(N,I)·N，N 必须已归一化</td><td><code>reflect</code>（第 10 章）</td></tr><tr><td><code>max(a, b)</code> / <code>pow(x, y)</code></td><td>漫反射背面钳 0 / 高光取幂</td><td>第 10 章</td></tr></tbody></table><h2 id="webgl-调用速查-按接线顺序" tabindex="-1">WebGL 调用速查（按接线顺序） <a class="header-anchor" href="#webgl-调用速查-按接线顺序" aria-label="Permalink to &quot;WebGL 调用速查（按接线顺序）&quot;">​</a></h2><h3 id="上下文与视口" tabindex="-1">上下文与视口 <a class="header-anchor" href="#上下文与视口" aria-label="Permalink to &quot;上下文与视口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>调用</th><th>干什么</th><th>首教</th></tr></thead><tbody><tr><td><code>canvas.getContext(&#39;webgl&#39;, { antialias, depth })</code></td><td>取上下文；depth: true 才有深度缓冲</td><td>第 2 章</td></tr><tr><td><code>gl.viewport(x, y, w, h)</code></td><td>把 NDC 操场四角对到画布四角</td><td>第 2 章</td></tr><tr><td><code>gl.clearColor(r, g, b, a)</code> / <code>gl.clearDepth(1)</code></td><td>清屏色 / 清深度值（默认 1）</td><td>第 2 / 8 章</td></tr><tr><td><code>gl.clear(COLOR_BUFFER_BIT | DEPTH_BUFFER_BIT)</code></td><td>清屏</td><td>第 2 / 8 章</td></tr><tr><td><code>gl.enable(DEPTH_TEST)</code> / <code>gl.enable(CULL_FACE)</code></td><td>开深度测试 / 开背面剔除（两者默认关）</td><td>第 8 章</td></tr></tbody></table><h3 id="着色器与程序" tabindex="-1">着色器与程序 <a class="header-anchor" href="#着色器与程序" aria-label="Permalink to &quot;着色器与程序&quot;">​</a></h3><table tabindex="0"><thead><tr><th>调用</th><th>干什么</th><th>首教</th></tr></thead><tbody><tr><td><code>gl.createShader(VERTEX_SHADER / FRAGMENT_SHADER)</code></td><td>开一个着色器空壳</td><td>第 2 章</td></tr><tr><td><code>gl.shaderSource(sh, src)</code> → <code>gl.compileShader(sh)</code></td><td>装源码并编译</td><td>第 2 章</td></tr><tr><td><code>gl.getShaderParameter(sh, COMPILE_STATUS)</code> → <code>gl.getShaderInfoLog(sh)</code></td><td>黑屏排查第一路：编译失败不抛异常，报错躺在这里</td><td>第 2 章</td></tr><tr><td><code>gl.createProgram()</code> → <code>gl.attachShader</code> × 2 → <code>gl.linkProgram</code></td><td>编译好的两段拼成可执行程序</td><td>第 2 章</td></tr><tr><td><code>gl.getProgramParameter / getProgramInfoLog</code></td><td>链接错误（varying 名字对不上等）从这里拿</td><td>第 2 章</td></tr><tr><td><code>gl.useProgram(prog)</code></td><td>换用哪个程序</td><td>第 2 章</td></tr></tbody></table><h3 id="缓冲与顶点属性" tabindex="-1">缓冲与顶点属性 <a class="header-anchor" href="#缓冲与顶点属性" aria-label="Permalink to &quot;缓冲与顶点属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>调用</th><th>干什么</th><th>首教</th></tr></thead><tbody><tr><td><code>gl.createBuffer()</code> → <code>gl.bindBuffer(ARRAY_BUFFER, buf)</code> → <code>gl.bufferData(ARRAY_BUFFER, data, STATIC_DRAW)</code></td><td>开箱、挂轨道、整箱倒数据（一次性上传）</td><td>第 2 章</td></tr><tr><td><code>gl.getAttribLocation(prog, &#39;a_position&#39;)</code></td><td>名字换格子号；返回 -1 = 名字对不上或被优化掉（黑屏排查第二路）</td><td>第 2 章</td></tr><tr><td><code>gl.enableVertexAttribArray(loc)</code></td><td>启用取料口；漏了就读常量默认值 (0,0,0,1)——三角形缩成看不见的点</td><td>第 2 章</td></tr><tr><td><code>gl.vertexAttribPointer(loc, size, FLOAT, false, stride, offset)</code></td><td>登记取料规则：几个分量一组、每行跨多少字节、从第几字节起</td><td>第 2 章；交错布局对账第 8 章（32/0/12）</td></tr><tr><td><code>gl.bindBuffer(ELEMENT_ARRAY_BUFFER, ibo)</code></td><td>索引缓冲挂另一条轨道</td><td>第 8 章</td></tr></tbody></table><h3 id="绘制" tabindex="-1">绘制 <a class="header-anchor" href="#绘制" aria-label="Permalink to &quot;绘制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>调用</th><th>干什么</th><th>首教</th></tr></thead><tbody><tr><td><code>gl.drawArrays(TRIANGLES / POINTS, first, count)</code></td><td>顺序画 count 个顶点</td><td>第 1 / 2 章</td></tr><tr><td><code>gl.drawElements(TRIANGLES, count, UNSIGNED_SHORT, 0)</code></td><td>按索引清单画，顶点复用</td><td>第 8 章</td></tr><tr><td><code>gl.drawArrays(LINES, …)</code></td><td>画线（线框、轨道圈）；<strong>背面剔除对线不生效</strong></td><td>第 8 章</td></tr></tbody></table><h3 id="uniform" tabindex="-1">uniform <a class="header-anchor" href="#uniform" aria-label="Permalink to &quot;uniform&quot;">​</a></h3><table tabindex="0"><thead><tr><th>调用</th><th>干什么</th><th>首教</th></tr></thead><tbody><tr><td><code>gl.getUniformLocation(prog, &#39;u_x&#39;)</code></td><td>名字换地址</td><td>第 3 章</td></tr><tr><td><code>gl.uniform1f / uniform3f / uniform1i</code></td><td>逐帧喂标量与向量；纹理单元号用 uniform1i</td><td>第 3 / 9 章</td></tr><tr><td><code>gl.uniformMatrix4fv(loc, false, mat4)</code></td><td>传矩阵；数据必须列主序，transpose 必须 false</td><td>第 5 章</td></tr></tbody></table><h3 id="纹理" tabindex="-1">纹理 <a class="header-anchor" href="#纹理" aria-label="Permalink to &quot;纹理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>调用</th><th>干什么</th><th>首教</th></tr></thead><tbody><tr><td><code>gl.createTexture()</code> → <code>gl.bindTexture(TEXTURE_2D, tex)</code></td><td>开纹理并挂轨道</td><td>第 9 章</td></tr><tr><td><code>gl.pixelStorei(UNPACK_FLIP_Y_WEBGL, 1)</code></td><td>上传时行序倒转——图片顶行落 v=1 顶边；不开则上下颠倒</td><td>第 9 章</td></tr><tr><td><code>gl.texImage2D(TEXTURE_2D, 0, RGBA, w, h, 0, RGBA, UNSIGNED_BYTE, data)</code></td><td>逐像素字节表上传</td><td>第 9 章</td></tr><tr><td><code>gl.texParameteri(MIN_FILTER / MAG_FILTER, NEAREST / LINEAR)</code></td><td>过滤：马赛克块 / 调匀。<strong>MIN 默认值要求 mipmap——只传第 0 级不改参数会采样全黑</strong>，本课程 MIN/MAG 同档绕开</td><td>第 9 章</td></tr><tr><td><code>gl.texParameteri(WRAP_S / WRAP_T, REPEAT / CLAMP_TO_EDGE)</code></td><td>包裹：平铺 / 拉边。WebGL1 非 2 幂尺寸只许后者</td><td>第 9 章</td></tr><tr><td><code>gl.activeTexture(TEXTURE0)</code> + <code>gl.uniform1i(loc, 0)</code></td><td>纹理单元与采样器对接</td><td>第 9 章</td></tr></tbody></table><h2 id="坐标变换链-mvp-流水线" tabindex="-1">坐标变换链（MVP 流水线） <a class="header-anchor" href="#坐标变换链-mvp-流水线" aria-label="Permalink to &quot;坐标变换链（MVP 流水线）&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>局部坐标 --(模型矩阵 M，场景树链乘)--&gt; 世界坐标</span></span>
<span class="line"><span>        --(视图矩阵 V，lookAt)--&gt; 眼空间</span></span>
<span class="line"><span>        --(投影矩阵 P)--&gt; 裁剪坐标（w 装着深度）</span></span>
<span class="line"><span>        --(÷w 透视除法)--&gt; NDC [-1,1]³</span></span>
<span class="line"><span>        --(viewport)--&gt; 屏幕像素</span></span></code></pre></div><p>矩阵乘法从右往左作用、顺序不可交换（第 5 章）；MVP 在 JS 侧预乘成一台再上传是常见习惯（第 6 章起演示的做法）。</p>`,25)])])}const p=d(r,[["render",c]]);export{g as __pageData,p as default};
